exec(open('/work/tmp/regressions.py').read().split("case('private-module'")[0])
case('shared-module',"mod a 'shared.just'\nmod b 'shared.just'\n", ['a::show','b::show'], {'shared.just':"@show:\n  echo {{module_path()}}\n"})
case('shared-overrides',"mod a 'shared.just'\nmod b 'shared.just'\n", ['a::x=A','b::x=B','a::show','b::show'], {'shared.just':"x := 'default'\n@show:\n  echo {{module_path()}} {{x}}\n"})
case('import-module',"import 'shared.just'\nmod b 'shared.just'\n", ['show','b::show'], {'shared.just':"@show:\n  echo {{module_path()}}\n"})
case('env-dotenv',"set dotenv-load\n[env('VALUE','recipe')]\n@show:\n  echo $VALUE\n", ['show'], {'.env':'VALUE=dotenv\n'})
case('env-export',"export VALUE := 'global'\n[env('VALUE','recipe')]\n@show:\n  echo $VALUE\n", ['show'])
case('env-body',"[env('VALUE','recipe')]\n@show default=`echo $VALUE`:\n  echo {{default}}\n  echo {{`echo $VALUE`}}\n", ['show'])
case('fn-backtick-export',"set unstable\nexport FOO := 'bar'\nf() := `echo $FOO`\n@show:\n  echo {{`echo $FOO`}}\n  echo {{f()}}\n", ['show'])
case('fn-indirect-capture',"set unstable\nx := 'outer'\ny := x\nf(x) := y\n@show:\n  echo {{y}} {{f('inner')}}\n", ['show'])
case('fn-duplicate-parameter',"set unstable\nf(x, x) := x\n@show:\n  echo {{f('first','second')}}\n", ['show'])
case('timestamp-invalid',"@show:\n  echo hello\n", ['--timestamp','--timestamp-format','%Q','show'])
